package com.yskj.shopify.web.controller;
import com.yskj.shopify.web.service.CustomStoreConnectionClient;import com.yskj.dao.dto.org.LoginedUser;import com.alibaba.fastjson.JSONObject;import javax.servlet.http.HttpSession;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;
@Controller public class CustomStoreConnectionController {
 private com.yskj.shopify.web.service.MerchantWebFacadeClient facade;
 @org.springframework.beans.factory.annotation.Autowired(required=false) public void setFacade(com.yskj.shopify.web.service.MerchantWebFacadeClient value){facade=value;}
 private final CustomStoreConnectionClient client;public CustomStoreConnectionController(CustomStoreConnectionClient client){this.client=client;}
 LoginedUser user(HttpSession session){var principal=session==null?null:session.getAttribute("logineduser");if(!(principal instanceof LoginedUser value)||value.getId()==null||value.getId().isBlank())throw new ResponseStatusException(HttpStatus.FORBIDDEN); return value;}
 JSONObject testable(LoginedUser user,String shop){var status=client.status(user,shop);if(!status.getBooleanValue("available"))throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE);if(!status.getBooleanValue("featureEnabled"))throw new ResponseStatusException(HttpStatus.CONFLICT);if(!status.getBooleanValue("canTest"))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return status;}
 String redirect(String shop){return "redirect:/stores?shop="+URLEncoder.encode(CustomStoreConnectionClient.shop(shop),StandardCharsets.UTF_8)+"#store-data-connection";}
 public String save(@RequestParam String shop,@RequestParam String apiBaseUrl,@RequestParam String sourceStoreId,@RequestParam String datasetEpoch,@RequestParam(defaultValue="") String apiToken,@RequestParam long expectedVersion,HttpSession session,RedirectAttributes flash){user(session);throw new ResponseStatusException(HttpStatus.FORBIDDEN,"连接配置仅由平台管理端维护");}
 public String probe(@RequestParam String shop,@RequestParam long expectedVersion,HttpSession session,RedirectAttributes flash){var u=user(session);testable(u,shop);try{var result=client.probe(u,shop,expectedVersion);if("VERIFIED".equals(result.getString("state")))flash.addFlashAttribute("successMessage","API鉴权与来源身份验证通过；签名未验证，尚未同步。");else flash.addFlashAttribute("errorMessage","连接验证未通过，请核对连接状态和配置。");}catch(RuntimeException failure){flash.addFlashAttribute("errorMessage","连接验证未完成，请检查权限、配置及服务状态。");}return redirect(shop);}
 public String page(@RequestParam String shop,HttpSession session,Model model){user(session);return redirect(shop);}
 @GetMapping("/stores/custom-connection") public org.springframework.web.servlet.view.RedirectView pageRequest(@RequestParam String shop,HttpSession session){user(session);var target=new org.springframework.web.servlet.view.RedirectView(redirect(shop).substring("redirect:".length()),true);target.setExposeModelAttributes(false);return target;}
 public static String csrf(HttpSession session){synchronized(session){Object value=session.getAttribute("customStoreConnectionCsrf");if(value instanceof String token)return token;String token=java.util.UUID.randomUUID().toString();session.setAttribute("customStoreConnectionCsrf",token);return token;}}
 static void checkCsrf(HttpSession session,String token){Object expected=session==null?null:session.getAttribute("customStoreConnectionCsrf");if(!(expected instanceof String value)||token==null||!java.security.MessageDigest.isEqual(value.getBytes(StandardCharsets.UTF_8),token.getBytes(StandardCharsets.UTF_8)))throw new ResponseStatusException(HttpStatus.FORBIDDEN);}
 @PostMapping("/stores/custom-connection/save") public String saveRequest(@RequestParam String shop,@RequestParam String apiBaseUrl,@RequestParam String sourceStoreId,@RequestParam String datasetEpoch,@RequestParam(defaultValue="") String apiToken,@RequestParam long expectedVersion,@RequestParam(name="_connectionCsrf",required=false) String csrf,HttpSession session,RedirectAttributes flash){user(session);checkCsrf(session,csrf);return save(shop,apiBaseUrl,sourceStoreId,datasetEpoch,apiToken,expectedVersion,session,flash);}
 @PostMapping("/stores/custom-connection/test") public String probeRequest(@RequestParam String shop,@RequestParam long expectedVersion,@RequestParam(name="_connectionCsrf",required=false) String csrf,HttpSession session,RedirectAttributes flash){user(session);checkCsrf(session,csrf);return probe(shop,expectedVersion,session,flash);}
 @PostMapping("/stores/custom-connection/source") public String sourceRequest(@RequestParam String shop,@RequestParam String sourceType,@RequestParam String connectorKey,@RequestParam long expectedVersion,@RequestParam(name="_connectionCsrf",required=false) String csrf,HttpSession session,RedirectAttributes flash){user(session);checkCsrf(session,csrf);throw new ResponseStatusException(HttpStatus.FORBIDDEN,"连接配置仅由平台管理端维护");}
}
